marker="function api(url,opt={}){"
insert=r'''function uploadWithProgress(url,formData,onProgress){
  return new Promise((resolve,reject)=>{
    const xhr=new XMLHttpRequest(); xhr.open('POST',backendUrl(url),true);
    if(token) xhr.setRequestHeader('Authorization','Bearer '+token);
    xhr.responseType='json';
    xhr.upload.onprogress=e=>{if(e.lengthComputable&&onProgress)onProgress(e.loaded,e.total)};
    xhr.onload=()=>{const d=xhr.response||{}; if(xhr.status>=200&&xhr.status<300)resolve(d); else reject(Error(d.error||`خطا (${xhr.status})`))};
    xhr.onerror=()=>reject(Error('اتصال هنگام آپلود قطع شد'));
    xhr.ontimeout=()=>reject(Error('زمان آپلود تمام شد'));
    xhr.timeout=0; xhr.send(formData);
  });
}
function ensureUploadHUD(){
  let el=$('zentoUploadHud'); if(el)return el;
  el=document.createElement('div');el.id='zentoUploadHud';el.className='zento-upload-hud hidden';
  el.innerHTML='<div class="zento-upload-hud-icon">⬆</div><div class="zento-upload-hud-copy"><b id="zentoUploadTitle">در حال آپلود</b><small id="zentoUploadMeta">آماده‌سازی…</small><div class="zento-upload-track"><i id="zentoUploadBar"></i></div></div><strong id="zentoUploadPercent">0%</strong>';
  document.body.appendChild(el); return el;
}
function showUploadHUD(title='در حال آپلود'){const el=ensureUploadHUD();el.classList.remove('hidden');$('zentoUploadTitle').textContent=title;$('zentoUploadMeta').textContent='در حال ارسال فایل…';$('zentoUploadBar').style.width='0%';$('zentoUploadPercent').textContent='0%';}
function updateUploadHUD(loaded,total){const p=total?Math.min(100,Math.round(loaded/total*100)):0;$('zentoUploadBar')?.style.setProperty('width',p+'%');if($('zentoUploadPercent'))$('zentoUploadPercent').textContent=p+'%';if($('zentoUploadMeta'))$('zentoUploadMeta').textContent=total?`${(loaded/1024/1024).toFixed(1)} / ${(total/1024/1024).toFixed(1)} MB`:'در حال ارسال…';}
function hideUploadHUD(){const el=$('zentoUploadHud');if(el){el.classList.add('done');setTimeout(()=>el.classList.add('hidden'),700)}}
'''
A=A.replace(marker,insert+marker,1)

